                if capacity > 0 and load + d > capacity:
                    continue
                score = (dist(current, c), dist(depot, c), d, c)
                if cand is None or score < cand_score:
                    cand = c
                    cand_score = score
            if cand is None:
                break
            route.append(cand)
            load += demand_of(cand)
            unassigned.remove(cand)
            current = cand

        routes.append(route)

    def route_load(rt):
        s = 0
        for c in rt:
            s += demand_of(c)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        total = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            total += dist(rt[i], rt[i + 1])
        total += dist(rt[-1], depot)
        return total

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route[:]
        route = route[:]
        improved = True
        while improved:
            improved = False
            best_delta = 0
            best_i = -1
            best_j = -1
            for i in range(n - 2):
                a = depot if i == 0 else route[i - 1]
                b = route[i]
                for j in range(i + 2, n):
                    c = route[j]
                    d = depot if j == n - 1 else route[j + 1]
                    delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                    if delta < best_delta:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i >= 0:
                route[best_i:best_j + 1] = route[best_i:best_j + 1][::-1]
                improved = True
        return route

    routes = [two_opt(r) for r in routes]

    # Repair: relocate to satisfy capacity where possible and reduce cost
    changed = True
    while changed:
        changed = False
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            if not routes[i]:
                continue
            for pos in range(len(routes[i])):
                c = routes[i][pos]
                d = demand_of(c)
                best_move = None
                best_gain = 0
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if capacity > 0 and loads[j] + d > capacity:
                        continue
                    base_i = route_cost(routes[i])
                    base_j = route_cost(routes[j])
                    ri = routes[i][:]
                    rj = routes[j][:]
                    ri.pop(pos)
                    for ins in range(len(rj) + 1):
                        rrj = rj[:]
                        rrj.insert(ins, c)
                        new_i = route_cost(ri) if ri else 0
                        new_j = route_cost(rrj)
                        gain = (base_i + base_j) - (new_i + new_j)
                        if gain > best_gain:
                            best_gain = gain
                            best_move = (i, j, pos, ins)
                if best_move is not None:
                    i2, j2, pos2, ins2 = best_move
                    c2 = routes[i2][pos2]
                    routes[i2].pop(pos2)
                    routes[j2].insert(ins2, c2)
                    changed = True
                    break
            if changed:
                break
        routes = [r for r in routes if r]

    # Final clean-up: merge empty/short routes deterministically and 2-opt again
    routes = [two_opt(r) for r in routes if r]
    return routes
